from common import *
B='010天外金球.txt'
make('qian_wanren','钱万人',B,
'钱万人曾是白老大的助手，也是少数敢与他对抗、武术造诣足以相提并论的人。被赶走后，他转入军旅，后来在张将军手下占据高位，以自身身手和官方权势追索金球。他可以轻易摔开白素，观察对手的松懈，在看似落败的局面里反过来制住卫斯理；这说明他既有真功夫，也有抓机会的机智，不能只凭最终被制服就写成无能的反派。他最终在卫家以人质和军法审判施压，却被白老大与同伴冒充部属反制。白老大揭出他曾替日本人做事的旧底，逼他在名誉、职位和实际为民办事之间作选择。他答应每半年做一件能让众人知道的有益之事，随后狼狈离开；原文没有展示承诺以后是否全部兑现。综合卡保留仍可行动的武术高手与高官身份，同时把畏惧旧首领、怕旧事曝光和容易依赖官威写进局限。他可以在新场景中做有用的事，却仍须以行动证明，不能只因一次被迫答应就自动获得正派结局。',
'被白老大制服并揭出旧事，答应定期为百姓办实事后获释；后续履约未证实。','高强武术与机会反制','长期中国武术训练，能近身摔制白素并抓住松懈制住卫斯理，结合枪械和公职威压。','对白老大的心理畏惧及旧事曝光风险显著；身手非超自然防御，官职需要组织支持。',[(560,588,'身手与师门旧事'),(2660,2699,'挟持与反制'),(2702,2741,'旧罪、条件与离去')],
'保住地位与自主，在权力和旧江湖关系夹击中求生。',[('对手认为已占上风','出现近身空隙','寻找一次迅速扭转控制的机会。'),('白老大揭出旧事','职位和名誉受到实际威胁','放下强硬姿态，承诺可核的补偿行动。'),('职责能惠及普通人','不会立即毁掉自身位置','尝试用机智履约，不能以口头答应代替结果。')],roles=['反派'],scores=(4,0,1,4,2,5),tier='强')
make('saren','萨仁',B,
'萨仁是协助白素进入封锁地区的年轻向导。他的叔父曾在巴黎向白家请求帮助，因此他初见白素就知道她的身份，却仍必须用实际路线和亲属关系争取信任。他熟悉只有少数人知道的小径、隐蔽通道和地方组织，是把异乡承诺接到具体行动的人。金球在当地不仅是奇物，也被争夺者视作政治与宗教权力的象征，萨仁的工作因而始终带着现实危险；他不会因接近所谓神物就获得超自然保护。卫斯理与白素后来重新追究金球的秘密，又让他卷入护送与追逐。他乘车时遭密集枪击，车子被打得千疮百孔，装物的盒子被抢走，他本人死亡。卫白感到自己促成了这场悲剧，但这种负疚不是证明萨仁只能作为替他们牺牲的道具。综合卡恢复最后清醒的向导形态，保留为共同体帮忙、希望被外来者信任的立场，也应能提出路线、暴露和撤退的实际条件。他可以勇敢承担任务，但不会无穷次以自身生命弥补别人的好奇。',
'在后续金球事件中遭车辆伏击，枪击死亡。','地方向导与隐蔽联络','熟悉封锁区的小径、接头地点和可信组织，能帮助外来者接近行动负责人。','常人身体无防枪能力；地方经验不能控制所有追踪者，需交通与实际接应。',[(349,381,'身份和向导路线'),(1638,1655,'伏击死亡及影响')],
'协助共同体守住重要事物，并让托付给自己的外来者安全走完路。',[('来客不信任身份','可以提供实际亲属或路线锚点','先解释和核实，避免逼迫同行。'),('封锁使常路不可行','仍有熟悉小径','选择隐蔽路线并说明代价。'),('任务范围不断扩大','护送危险超过初始安排','重新讨论人手和撤退，不把忠诚当无限承诺。')],roles=['单书主线人物'],dead=True)
make('zhangmo','章摩',B,
'章摩是政治与宗教逃亡行动中的重要负责人，也是白老大的旧友。失去金球被视为失去天赐权力象征，因而他组织请求白家帮助，接待独自到来的白素，希望她兑现远方许下的承诺。他的地位能联系行动委员会、秘书和地方协助者，却不能抹平封锁与对手控制区的危险。故事中的金球后来被确认关联微小外星生命，他所理解的启示也被卫斯理重新解释为某些人在安静状态下能够接收的有限信息；这种解释并没有让章摩变成随意联系全宇宙的神通者。他提供的建议引导卫斯理尝试静坐，成为认识金球的重要转折，后续秘书却也表示他最近没有特别感应。综合卡保留流亡领袖的责任和宗教理解，不强迫他立即采用另一套语言否定全部信仰，也不把他隐名直接指定为现实历史人物。面对新的异常，他可以先从信仰框架解释，同时允许把消息与实际后果相核对；作为领袖，他必须关心被派出者的风险，而非只要求他人证明对神物的忠诚。',
'仍在流亡组织中，金球归还联络经秘书进行；末期没有新的特别感应。','组织斡旋与有限感应','通过既有政治宗教网络协调行动；曾以启示理解金球生命的信息，接收条件有限。','不能保证感应出现、不能召神或心控；地位只约束实际支持者，现实身份不强定。',[(379,396,'行动委员会和身份'),(1949,1955,'启示及静坐推论'),(2484,2487,'末期未有感应')],
'保存共同体在流亡中的希望与合法性，理解被视为神圣的金球。',[('神圣象征落入敌手','会影响追随者信心','组织求助并考虑实际救援条件。'),('启示能用另一机制解释','证据尚未否定意义','检验实际信息而非立刻排斥异说。'),('信众要求确定答案','自己没有新感应','承认沉默，不编造神谕维持权威。')],roles=['单书主线人物'])
make('tianwai_zhang_general','张将军',B,
'张将军是控制大片地区和众多人口的军方人物，金球事件使他把白素看成掌握重要地点信息的俘虏。他的姓名只以普通称呼出现，不能据背景暗示补成某位现实将领。追索金球并不只出于珍宝价值，更涉及对具有权力象征的事物的占有；白素记得地图这一点使她获得暂时谈判空间，也使他能够要求她随军返回神宫。身边的钱万人提供真实的近身压制，使将军的命令不仅靠纸面头衔执行。原文并未让他亲手展示高强武术、神秘法术或金球控制权限，也没有说明后期每一次针对卫白的攻击都由他本人直接下令。综合卡保留掌权者、审讯者和任务安排者的最后可核形态，军队属于有辖区、补给与层级的机构资源，不能当成瞬间生成的个人召唤。他会用秩序、安全和权力象征说明行动，却必须面对被囚者仍能隐瞒、谈判或反抗的现实。新的对立可从他需要地图而无法随意杀害知情者开始，不必永远重复强令搜宫一条情节。',
'追索金球并安排押解白素，个人末后命运未交代。','军政控制与押解部署','在辖区内通过部属、武装封锁和审讯获取信息，依赖钱万人等实际执行者。','没有个人超能力；军队需要命令传达与现场控制，不能自动知道秘密地点。',[(460,488,'身份及地图交涉'),(560,589,'依靠钱万人压制和押解'),(663,665,'白素确认俘虏身份')],
'把象征权力的重要物件掌握在己方手中，维持控制区秩序。',[('俘虏掌握独有地图','强行处置会失去线索','保留其生命并施压合作。'),('部属能形成压制','现场尚未可控','用实际守卫和押解执行命令。'),('神圣象征影响人心','军事占领仍不充分','试图占有或解释象征，不能当作已获所有人认同。')],roles=['反派'],scores=(1,0,2,2,3,2),tier='并')
make('wang_fengyuan','王逢源',B,
'王逢源是住在美国、经营或从事精密仪器制作工作的科学技术人员，也是卫斯理可以求助的朋友。平日为工作方便住工厂宿舍，假期才回有完善地下工作室的别墅，显示他把实验条件与日常生活紧密结合。他接纳卫白研究金球，以微小摄像管、显微镜与精细切剖尝试观察内部；卫斯理顾虑不能损坏借物时，他也必须面对技术可能与他人承诺之间的限制。发现金球会缓慢复原后，两人越研究越兴奋，甚至忽略休息和生活，白素眼中的荒唐正是专注过度的另一面。他有耐心移动镜头、反复寻找微观结构，却最终承认没有进一步发现，停止无结果的尝试。真正的外星沟通后来通过另一条途径发生，不能倒过来把所有谜底算成他的研究成果。综合卡保存有设备、好奇且能合作的工程研究者，不给他无限实验室或万能鉴定。他可以从一个异常细节展开新方案，也应在朋友急于下结论时要求可重复的观察，尊重借来的物件和里面可能存在的生命。',
'在美国完成金球显微观察尝试，没有进一步发现后停止；仍为可行动研究者。','精密仪器与显微观察','熟悉微型成像、加工和实验工具，可在工作室内进行耐心的内部观察。','需要实际工具与样品；不能仅靠显微镜读懂外星文明，金球自愈不是他的能力。',[(1662,1695,'身份、设备和承诺冲突'),(1863,1881,'切剖、耐心与无结果')],
'用精密的观察和加工把奇异物件变成可以验证的问题。',[('样品极其稀有','观察可能破坏它','先讨论许可与损伤条件。'),('新机制似乎允许大胆实验','兴奋超过谨慎','设置停止点，不把复原想象成绝对安全。'),('长期没有发现','继续重复只耗尽精力','承认方法局限并暂停，等待新证据。')],roles=['单书主线人物'])
make('goldball_micropeople','金球微型外星人',B,
'金球中的微型外星人是一个共同逃离母星灾难的群体。它们提前推算小行星脱轨，合力建造以缓慢生长微生物为材料的大飞船，却因起飞稍迟一起落到地球；人类眼中的一呎金球，是足以容纳全体的巨大避难所。长期侦察使它们理解部分地球环境，也找到已被砌成神宫基石的家乡残体。它们能驾驶六人小飞船高速移动，以微弱电波向少数处于安静状态的人交流，还自述拥有伤人光束与穿透能力；这些本领没有使它们克服抬升母星残体、让母船起飞的尺度与重力难题。三十名领袖共同向卫斯理求助，被拒后没有用杀人迫使服从，还提醒白素独自涉险。真正的急迫来自必要气体将尽，最后估计全体只剩半年生命；此后联络消失，是否全部死亡没有直接见证。综合卡保留末次明确生存的群体、有限飞船与气体约束，不把金粉外观写成隐形神灵，也不把和平当成绝对不会防卫。它们可因思乡急于求助，却仍需要尊重尺度不同的盟友所能承担的代价。',
'自述关键气体仅够约半年，随后不再回应；全灭为担忧和推定，未亲见确认。','微型飞船、有限脑波联络与微观工程','六人小船高速移动可作侦察与物理穿透，特定宁静接收者能听到微电波；母船材料缓慢再生。','不能抬起母星残体或使母船自行离地；气体有限，接收频率不通用，杀伤上限多为自述未实测。',[(1991,2031,'沟通、母船和侦察'),(2033,2108,'家园、三十领袖、能力及重力边界'),(2194,2235,'提醒与可见飞船'),(2430,2475,'气体枯竭及无回应')],
'让共同体重返家乡并延续生命，在求援中避免以优势伤害地球人。',[('对方无法听见声音','脑波条件不合','用飞船排列可见符号或等待安静接收。'),('救援要求超过盟友能力','对方明确拒绝','解释需求并协商，不以伤害强迫。'),('气体继续减少','母星残体仍受压','优先寻可执行运输方案，不能凭意愿消除重力。')],roles=['非人主角'],scores=(2,3,2,3,3,2),tier='强',limits=(3,4,1),appearance='个体肉眼难见；六人飞船在人眼中是针尖般金点，母船为金球。',destruction='微小飞船自述可穿物、伤害神经及发射致命光束；未展示大尺度爆破。',durability='微观身体对人类轻触也可能脆弱，飞船保护有条件，不是概念无敌。',speed='小船极快，以人眼难跟踪为已示表现，不能量化为瞬移。',energy='有飞船光束的自述，强度不超出文本所称伤人层次。',stamina='寿命较长但缺必要气体，终局有约半年生存期限。')
cov(B,[('白素','weisili_bai_su','系列主角','取球、救援与坚持'),('白老大','weisili_bai_laoda','重要配角','旧交及结尾救人'),('钱万人','qian_wanren','反派','高强武术、官方胁迫及条件释放'),('萨仁','saren','单书主线人物','向导、护送和遇害'),('章摩','zhangmo','单书主线人物','行动组织及启示'),('张将军','tianwai_zhang_general','反派','拘押和夺取象征'),('王逢源','wang_fengyuan','单书主线人物','独立研究段落'),('微型外星人','goldball_micropeople','非人主角','求援、能力与生存困境'),('老蔡','weisili_lao_cai','重要配角','家庭接应')],[('未名僧侣、游击队负责人、章摩秘书及白老大同行老人','有协助但无姓名分化或独立跨书主线，不杜撰个人完整传记。'),('袭击车队枪手及士兵','从属武装执行者，未证实独立指挥人格。')],['金球生命可能死亡而非确认复活；微小文明不承袭整个外星科技总和。'])
